package main

import (
	"fmt"
	"math"
	"math/bits"
	"time"
)

func floorMod128(hi int64, lo uint64, y int64) uint64 {
	yu := uint64(y)
	if hi >= 0 {
		return rem128(uint64(hi), lo, yu)
	}
	mlo := -lo
	mhi := -uint64(hi)
	if lo != 0 {
		mhi--
	}
	if r := rem128(mhi, mlo, yu); r != 0 {
		return yu - r
	}
	return 0
}

func quo128(hi int64, lo uint64, y int64) int64 {
	yu := uint64(y)
	if hi >= 0 {
		q, _ := bits.Div64(uint64(hi), lo, yu)
		return int64(q)
	}
	mlo := -lo
	mhi := -uint64(hi)
	if lo != 0 {
		mhi--
	}
	q, _ := bits.Div64(mhi, mlo, yu)
	return -int64(q)
}

func rem128(hi, lo, y uint64) uint64 {
	if hi >= y {
		hi %= y
	}
	return bits.Rem64(hi, lo, y)
}

func windowStartWide(sec, nsec, w int64) time.Time {
	uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
	if sec < 0 {
		uhi -= 1e9
	}
	hi := int64(uhi)
	lo := ulo + uint64(nsec)
	if lo < ulo {
		hi++
	}
	fmt.Printf("  t: hi=%d lo=%d\n", hi, lo)
	rem := floorMod128(hi, lo, w)
	fmt.Printf("  rem=%d\n", rem)
	if lo < rem {
		hi--
	}
	lo -= rem
	ns := floorMod128(hi, lo, 1e9)
	if lo < ns {
		hi--
	}
	lo -= ns
	return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
}

func main() {
	at := time.Unix(0, math.MinInt64)
	fmt.Println("at sec:", at.Unix(), "nsec:", at.Nanosecond())
	got := windowStartWide(at.Unix(), int64(at.Nanosecond()), int64(10*time.Second))
	fmt.Println("got:", got.UTC())
	// expected: MinInt64 ns = -9223372036854775808; floor to 1e10 -> -9223372040000000000 ns
	fmt.Println("want:", time.Unix(-9223372040, 0).UTC())
}
